"""Use the current unit 9 reader unchanged in design for the final A2 unit."""
import json,re
from pathlib import Path
R=Path('kitaplar/lise-a2/geziyorum');answers={}
def add(n,title,items,note=None):
 answers[str(n)]={'sections':[{'title':title,'items':items}]}
 if note:answers[str(n)]['note']=note
add(1,'Hazırlık · Örnek cevaplar',['Kapakta Mostar Köprüsü, Kız Kulesi, Galata Kulesi, Registan Meydanı, Ayasofya ve Sultanahmet Camii görülüyor.','Türkiye, Bosna Hersek ve Özbekistan ile ilgili yerler var.','Bu ünitede seyahat, rezervasyon, konaklama, yol tarifi ve gezi izlenimleri üzerine çalışacağız.'],'Kendi ülkenizdeki eserler için kişisel cevaplar kabul edilir.')
add(2,'Tatil anketi · Örnek cevap',['Doğa tatilini tercih ederim. Arkadaşlarımla trenle gider, küçük bir pansiyonda kalırım.','Yapmayı sevdiğim beş etkinlik: doğa yürüyüşü yapmak, kitap okumak, bisiklet sürmek, yüzmek ve yeni yerler keşfetmek.'],'Anket kişiseldir; seçenekler arasında tek bir doğru cevap yoktur.')
add(3,'Afişler ve okuma',['Demet Otel: Beşiktaş; kişi başı bir gece 1275 TL; kahvaltı ve akşam yemeği dâhil; Ortaköy Camisi ve Yıldız Parkı yakınında.','Çalış Otel: Sultanahmet; kişi başı bir gece 600 TL; kahvaltı ve Türk hamamı; Ayasofya ve Sultanahmet yakınında.','Gültekin Otel: Taksim; kişi başı bir gece 750 TL; kahvaltı, havuz ve spor salonu; Taksim Meydanı, Dolmabahçe Sarayı ve Atatürk Kültür Merkezi yakınında.','3. etkinlik: tatil bileti. Vedat Bey ailesi için İstanbul uçak bileti alıyor.','Okuma: 19 Ağustos Cuma günü saat 20.00; yüzde 50 indirim; kişi başı 1750 TL; dört kişi.'],'Fiyatlar ve hizmetler ders kitabındaki kurmaca afişlere aittir; güncel ticari teklif değildir. Özgün S.058 kaydı henüz eklenmedi.')
add(4,'Otel seçimi · Metne göre',['Aile İstanbul’da bir hafta tatil yapacak. Biletleri yüzde 50 indirimle almışlar.','Vedat Bey deniz manzaralı ve merkeze yakın Demet Otel’i öneriyor.','Sare havuzlu oteli, yani Gültekin Otel’i beğeniyor.','Amina Hanım, fiyatı daha uygun olan seçenekleri değerlendiriyor; alışveriş merkezlerine yakın, spor salonlu otelden söz ediyor.','Almir, Ayasofya ve Sultanahmet’in yanındaki Çalış Otel’i öneriyor.','Kelime örnekleri: uçak bileti, rezervasyon, indirim, kampanya, otel, deniz manzaralı, kahvaltı dâhil, akşam yemeği dâhil, spor salonu.'])
add(5,'Okuduğunu anlama',['5-a: 1. Türk Hava Yolları’ndan. 2. İstanbul’a. 3. 19 Ağustos Cuma. 4. 20.00’de. 5. Yüzde 50. 6. 1750 TL. 7. Bir hafta, yedi gün altı gece. 8. Daha güvenli ve daha kısa sürdüğü için. 9. Ailece değerlendiriyorlar; son seçimi çocuklar bildiriyor.','5-b: Gültekin → 1, 3, 4, 5, 7; Çalış → 1, 8, 10; Demet → 2, 6, 9.','5-ç: Sare → Gültekin; Vedat → Demet; Almir → Çalış. Amina’nın olumlu değerlendirdiği otel → Gültekin; ancak metinde kesin bir tercih cümlesi yok.'],'Amina’nın tercihi, spor salonu ve alışveriş merkezi ipuçlarına göre yorumlanır. Bütün otellerde kahvaltı sunuluyor; tablo 1. özellik ile 2. özelliği ayrı kutularla sınıflandırıyor.')
add(6,'Konuşma ve söz varlığı',['Örnek: Çalış Otel’i seçerim; tarihî yerlere yakın ve fiyatı daha uygun.','Uçakla ilgili fiiller: kalkmak, uçurmak, gitmek, inmek, uçmak, kullanmak. “Oturmak” da yolcunun uçaktaki eylemi olarak kullanılabilir.','Örnekler: Uçak havalimanından kalkıyor. Pilot uçağı uçuruyor. Uçak birazdan havalimanına inecek.'],'Oyun soruları kişisel seyahat deneyimlerine göre cevaplanır.')
add(7,'Cümle kurma ve rezervasyon',['1-c: 2. Uçak havalimanından kalkıyor. 3. Pilot uçağı uçuruyor. 4. Uçak birazdan havalimanına inecek.','2. etkinlik için örnek zincir: Uçak kalktı. Uçak havaalanından kalktı. Uçak havaalanındaki pistten kalktı. Uçak saat yedide İstanbul havaalanındaki pistten kalktı. Uçak İstanbul’dan Trabzon’a gitti. Uçak Trabzon havaalanına indi.','Dinleme 1-b: rezervasyon; rezervasyon. Çağrı merkezi ve müşteri hizmetleri, verilen iki boşluğun yerine aynı doğal yapıda gelmez.','Rezervasyon örnekleri: otel, uçak, restoran, nikâh salonu. Hastane ve banka için genellikle “randevu” denir; spor salonunda ders veya saha için rezervasyon yapılabilir.','Gerekli bilgiler: 1, 2 ve 5; gereken ayrıntılar kuruma göre değişebilir.'])
add(8,'Görevli ve müşteri',['3-a: Görevli → 1, 3, 4, 6, 8, 10, 12. Müşteri → 2, 5, 7, 9, 11, 13.','Sonraki yazılı cümlelerden bilinenler: Vedat Demiroviç adına dört kişilik aile odası; giriş 19 Ağustos 2022; yedi gün altı gece; otelde ödeme tercihi.','Telefon, e-posta, rezervasyon kodu ve yalnız dinleme ile öğrenilen diğer ayrıntılar S.059 olmadan kesinleştirilemez.'],'Özgün S.059 kaydı bulunmadığı için rezervasyon formunun bütün alanlarına tahminî bilgi yazılmadı.')
add(9,'Tekrar isteme ve uçuş kuralları',['5. etkinlik: Almir → 1, 3, 5, 6, 8, 10. Görevli → 2, 4, 7, 9.','Örnek rezervasyon diyaloğu: “İki kişilik oda ayırtmak istiyorum.” “Hangi tarihlerde kalacaksınız?” “12–14 Temmuz arasında.”','V.012 olmadan videoya göre doğru/yanlış anahtarı verilemez. Genel dil çalışması için yanlış cümleleri düzeltme örnekleri: Valizleri koridora koymayın; acil durumda görevlilerin yönlendirmelerine uyun; kalkış ve inişte masaları kapalı, koltuğu dik tutun.'],'4. etkinliğin tuş numaraları S.059’daki anonsa bağlıdır. Eksik ses/video kaydının dökümü veya kesin cevap anahtarı üretilmedi.')
add(10,'Anonslar ve tatil afişleri',['2. etkinlik: 1 havalimanı; 2 metro; 3 sinema; 4 uçak; 5 hastane; 6 telefon; 7 cadde.','Kaynak kutuda “hastane” yok, “iş yeri” var. Beşinci anons dahiliye bölümündeki hasta ve kan ihtiyacından söz ediyor; bu nedenle metnin anlamına göre hastane denmelidir.','Uyarı örnekleri: Sigara içmeyiniz. Telefonla konuşmayınız. Yiyecek ve içecek getirmeyiniz. Evcil hayvanla girmeyiniz. Fotoğraf çekmeyiniz.','Tatil afişleri: deniz tatili 5 gece 6 gün ve 35.000 TL; piramit gezisi 4 gece 5 gün ve 22.500 TL; uzay tatili 3 gece 4 gün ve 150.000 TL.'],'Cevaplar yazılı anonslara göredir; S.060 ile karşılaştırılamadı. Tatil afişleri dil etkinliğidir; güncel hizmet teklifi değildir.')
add(11,'Rol oynama · Örnek',['Müşteri: Merhaba, hafta sonu için iki kişilik oda ayırtmak istiyorum. Görevli: Kaç gece kalacaksınız? Müşteri: İki gece. Kahvaltı fiyata dâhil mi? Görevli: Evet, dâhil.','Bilet diyaloğu: “Cumartesi sabahı için iki bilet alabilir miyim?” “Nereye gitmek istiyorsunuz?” “İstanbul’a.”','Hazırlık örneği: Kimliğimi, biletimi, telefonumu, şarj cihazımı ve hava durumuna uygun kıyafetlerimi hazırlayacağım.'],'Formlarda kendi rol oyununuz için belirlediğiniz bilgileri kullanın; örnek bilgiler gerçek bir rezervasyon oluşturmaz.')
add(12,'Otel Maceramız · Problem',['Otel evcil hayvan kabul etmiyor; aile bunu önceden araştırmamış.','Kedi otele alınmıyor. Aile giriş yapamıyor, ücret iadesi alamıyor ve daha pahalı bir otel buluyor.','Örnek öneri: Rezervasyondan önce evcil hayvan ve iptal/iade koşullarını sorun; verilen bilgileri yazılı olarak saklayın.'],'Üstteki oyun kişisel deneyimler ve tercihlerle oynanır.')
add(13,'Deniz Maceram ve tatil planı',['Deniz Maceram: Denizdeki cam anlatıcının ayağını kesiyor. Hastaneye gidiyor ve doktor müdahale ediyor.','Örnek çözüm önerileri: Çöpleri denize atmayın; sahili temiz tutun; tehlikeli atıkları ilgili görevlilere bildirin.','Hafta sonu planı örneği: Ailemle göl kıyısına gideceğim. Otobüsle ulaşacağım, iki gece pansiyonda kalacağım ve doğa yürüyüşü yapacağım.'],'Rezervasyon formu, öğrencinin kendi planına göre doldurulur.')
add(14,'Şikâyet ve değerlendirme · Örnek',['Havuz kirli. Lütfen havuzu temizleyin.','Klima bozuk. Lütfen klimayı tamir edin.','Buzdolabı soğutmuyor. Lütfen kontrol edin.','Plajda şemsiye yok. Lütfen şemsiye getirin.','Havlular değiştirilmemiş. Lütfen temiz havlu verin.','Örnek e-posta: Sayın Yetkili, odamızdaki klima çalışmıyor ve havlular değiştirilmemiş. Klimanın kontrol edilmesini ve temiz havlu verilmesini rica ederim. İlginiz için teşekkür ederim.'],'Değerlendirme puanları öğrencinin oluşturduğu konaklama deneyimine göre verilir.')
add(15,'İstanbul haritası',['1-c: 1 b — karşısında; 2 ç — arasında; 3 b — ortasında; 4 a — karşısında.','Haritada Galata ve Kız kuleleri, Topkapı ve Dolmabahçe sarayları, Ayasofya ve Sultanahmet camileri ve Alman Çeşmesi yer alıyor.','Örnek: İlk defa gittiğim şehirde tarihî merkezi gezmek ve yerel yemekleri tatmak isterim.'],'Yer ilişkileri sayfadaki şematik haritaya göredir.')
add(16,'Almir ve Ailesi İstanbul’da',['Aile, Ayasofya Camisi’nin arka sokağındaki otelde kalıyor.','Eminönü iskelesine yürüyerek, sonra Üsküdar’a vapurla gidecekler. Murat tramvayı da öneriyor ama aile yürümek istiyor.','Yol: Tramvay hattını takip edin; sağdaki Gülhane Parkı’nı geçin; dümdüz ilerleyin; Eminönü iskelesine ulaşın.','Gezi planı: Üsküdar’daki tarihî yerler, Kız Kulesi, Galata Kulesi; ertesi gün Topkapı Sarayı, Ayasofya ve Sultanahmet Camisi.'],'Yazılı metne göre cevaplandı. Özgün S.061 kaydı henüz eklenmedi.')
add(17,'Okuduğunu anlama',['4: 1. Üsküdar sahilinde. 2. Eminönü’ne yürüyerek, Üsküdar’a vapurla. 3. Tramvay. 4. Yürüyerek. 5. Sare İstanbul’u çok beğeniyor ama kalabalık buluyor. 6. Amina Türk kahvaltısını, menemen ve gözlemeyi çok beğeniyor.','Güzergâh: Ayasofya → Gülhane Parkı → Eminönü iskelesi → vapur → Üsküdar.','6. etkinlik: Tercih/teklif → 1 ve 5; gözlem/izlenim → 2, 3, 4, 6 ve 7.'],'Sepetleri bu iki gruba göre kontrol edin; harita üzerindeki çizgilerle metnin güzergâhını karşılaştırın.')
add(18,'Kroki ve yol tarifi',['7-a / 1. boşluk: Sevgi Eczanesine. Şeker Pastanesinden ışıklara ilerleyip sola dönün; üstteki caddeden sola dönün; otobüs durağının solundaki eczaneye ulaşırsınız.','Örnek diyalog: “Affedersiniz, kırtasiyeye nasıl gidebilirim?” “Cadde boyunca düz yürüyün. Işıklardan sağa dönün. Kırtasiye yolun sonunda.”','Nasrettin Hoca’ya şehir tanıtımı örneği: Şehrimize otobüsle gelebilirsiniz. Merkezdeki parkı ve müzeyi gezebilirsiniz. Yerel yemekleri tatmanızı öneririm.'],'Krokiye bağlı boşluklar için yön ve bakış açısı görselle birlikte değerlendirilir; doğrulanmamış varış adı kesin cevap olarak eklenmedi.')
add(19,'Trafik ve yaya kuralları',['1. etkinlik eşleştirme: 1-c, 2-e, 3-b, 4-a, 5-d, 6-ç, 7-g, 8-ğ, 9-f.','2. etkinlik eşleştirme: 1-b, 2-ç, 3-g, 4-a, 5-c, 6-d, 7-e, 8-f.','Yayalar için anahtar ifadeler: üst/alt geçidi kullanmak; araçların önünden ve arkasından geçmemek; dikkati dağıtmamak; kaldırımdan yürümek; geçmeden önce sola-sağa-sola bakmak; görevlilerin yönlendirmelerine uymak.','Sürücüler için: emniyet kemeri takmak; aşırı hız yapmamak; takip mesafesini korumak; gereksiz şerit değiştirmemek; yayalara yol vermek; işaretlere uymak; geçitte yavaşlamak; hatalı sollama yapmamak.'],'Harf eşleştirmesinde görseldeki hareketi bu kurallarla karşılaştırın.')
add(20,'Uyarılar ve Seyahat Günlüğüm',['Uyarı örnekleri: Yolda oyun oynamayın. Yaya geçidini kullanın. Telefonla ilgilenirken karşıya geçmeyin. Sürücü: emniyet kemerini tak, hız sınırına uy ve yayalara yol ver.','Yazılı metinde Mostar Köprüsü, Neretva Nehri, Blagaj ve Sarı Saltuk Tekkesi anlatılıyor.','Köprüden atlama, metinde anlatılan yerel gelenektir; öğrenciye önerilen bir etkinlik değildir.'],'S.062 bulunmadığı için dinlemeyle doldurulacak sözcükler tahmin edilmedi.')
add(21,'Semerkant, Buhara ve İstanbul',['Yazılı metne göre: Semerkant’ta Registan Meydanı ve Bibi Hanım; Buhara’da tarihî yapılar; İstanbul’da Kız ve Galata kuleleri anlatılıyor.','Özbek pilavı ve çay; Bosna Hersek’in böreği ve kahvesi; İstanbul’da Türk kahvesi ve yemekler anılıyor.','Galata Kulesi’nin zindan ve gözlemevi olarak kullanıldığı, seyir terasından şehrin görülebildiği yazıyor.','Galata Kulesi ile ilgili evlilik anlatısı bir inanış olarak verilmiştir.'],'S.062’ye bağlı boşluklar tamamlanmadı. Ulaşım bilgileri kaynak metne aittir; güncel seyahat rehberi olarak doğrulanmadı.')
add(22,'Deyimler ve metin özeti',['3-a: Cesaret göstermek → korkmamak, yiğitlik; hayran olmak → çok beğenmek; yeme de yanında yat → çok lezzetli yemekler için söylenen söz; adım adım gezmek → her tarafı dolaşıp görmek.','Bosna Hersek: Mostar Köprüsü, Blagaj, Sarı Saltuk Tekkesi; börek ve kahve.','Özbekistan: Semerkant, Registan, Bibi Hanım, Buhara; Özbek pilavı ve çay.','İstanbul: Kız Kulesi, Galata Kulesi, Üsküdar; vapurla gezi ve tarihî merkezde yürüyüş.','Üç öneri örneği: tarihî yerleri gezmek, yerel yemekleri tatmak, uygun ulaşımı seçmek.'],'Metnin eksik bırakılmış ayrıntıları S.062 olmadan kesinleştirilemez.')
add(23,'Şehir tanıtımı ve yakın anlamlılar',['“Gezmek” ile ilişkili ifadeler: uğramak, ziyaret etmek, seyahat etmek, dolaşmak, bir yere gitmek, yolculuk etmek. “Almak” ve “uyumak” yakın anlamlı değildir.','Gezi örnekleri: geziye gitmek, geziye çıkmak, geziden dönmek, yaz gezisi, kış gezisi, kültür gezisi, doğa gezisi, gezi yeri, gezi mekânı, gezi türü, gezi süresi.','Örnek: Geziye çıkmadan önce güzergâhı araştırdık. Şehir merkezini yürüyerek dolaştık.','Atasözü, okumanın ve farklı yerleri görerek deneyim kazanmanın bilgiye katkısını vurgular.'],'Şehrinizin yerleşim yerleri, kültür merkezleri ve yemekleri için yerel bilgiye dayalı cevaplar verin.')
add(24,'Türkü ve efsane anlatma',['Türküde “ley, lim, limi, lüm” nakarat heceleridir; bağımsız sözlük anlamları yoktur.','“Daşları”, “taşları” kelimesinin ağız özelliği taşıyan biçimidir. “Yarı gördüm” sözündeki “yarı”, sevgili anlamındaki “yar”ın belirtme biçimidir.','“İstanbul’un Âşıkları” görseli için örnek: Galata Kulesi ile Kız Kulesi’nin birbirlerine seslendiği bir hikâye yazılabilir.'],'Özgün M.007 türkü kaydı ve kodsuz efsane dinlemesi sağlanmadı. Kelime sesleri türkü icrasının yerine sunulmuyor.')
add(25,'Adres bulma oyunu',['Örnek diyalogdaki hedef Asalet Emlak’tır. Yol: Gül Sokak’tan Bulvar Caddesi’ne geç; ışıklardan karşıya geç; Dolunay Sokak’a gir; düz git; Kırtasiye’den sonra solda.','Yeni diyaloglarda başlangıç noktasını, yönleri ve varış yerinin konumunu açıkça söyleyin.','Örnek: “Bulvar Caddesi boyunca ilerleyin. İlk sokaktan sağa dönün. Müze solda.”'],'Kendi şehrinizin krokisi ve yeni yol tarifleri açık uçludur.')
add(26,'E-posta ve afiş',['Sude bilgi almak için e-posta yazıyor.','Ülkeye gelmeden önce hazırlık, ulaşım, mevsim, kalış süresi, yemekler, gezilecek yerler, hediyelikler ve bütçe hakkında soruyor.','Örnek cevap: Sevgili Sude, şehrimize geldiğinde merkezdeki tarihî yerleri gezebiliriz. Otobüsle ulaşım kolay. İlkbaharda hava ılıman olur. Kaç gün kalacağını yazarsan birlikte plan yapabiliriz. Görüşmek üzere.','E-posta: uygun hitap, açık amaç, ayrıntılı bilgi, sorulara cevap, teşekkür ve uygun kapanış.'])
add(27,'Görmek Gerek: Kız Kulesi',['V.013 özgün videosu bulunmadığından tarih, kat sayısı, mesafe, yapı malzemesi ve videoya bağlı diğer ayrıntılar tahmin edilmedi.','İzleme sonrası: geçmiş zamanlı fiilleri belirleyin; kuleyle ilgili tarihleri ve kullanım amaçlarını videodaki sıraya göre not alın.'])
add(28,'Proje: Hayallerimdeki şehir',['Şehrin adını, yerini, özelliklerini, ulaşımını, gezilecek yerlerini ve etkinliklerini belirleyin.','Afiş veya maket hazırlayın; yol gösteren levhalar tasarlayın; tanıtım metni yazın.','Video hazırlayıp sınıfta sunun. Arkadaşlarınızın değerlendirmesini alın.','Örnek fikir: Yeşilşehir’de araçlar yerine bisiklet yolları, geniş parklar ve küçük elektrikli otobüsler var.'],'Bu proje açık uçludur; tek bir doğru şehir tasarımı yoktur.')
for n in [29,30]:add(n,'Kapanış',['International Maarif Program — Uluslararası Maarif Programı logosu.','Bu sayfada cevaplanacak bir etkinlik bulunmuyor.'])
(R/'answers.json').write_text(json.dumps(answers,ensure_ascii=False,separators=(',',':')))
