h=re.sub(r'<nav class="unit-navigation" aria-label="Üniteler arasında geçiş">.*?</nav>','<nav class="unit-navigation" aria-label="Üniteler arasında geçiş"><a class="unit-nav-button" href="../bir-hikayem-var/">← Bir Önceki Ünite</a><button class="unit-nav-button" disabled title="Lise A2 kitabının son ünitesindesiniz">Son Ünite</button></nav>',h,count=1)
h=re.sub(r'const UNIT_ANSWERS=.*?;\n',lambda m:'const UNIT_ANSWERS='+json.dumps(answers,ensure_ascii=False,separators=(',',':'))+';\n',h,count=1)
