p=Path('kitaplar/lise-a2/bir-hikayem-var/index.html');h=p.read_text().replace('<button class="unit-nav-button" disabled title="10. ünite henüz hazırlanmadı">Bir Sonraki Ünite →</button>','<a class="unit-nav-button" href="../geziyorum/">Bir Sonraki Ünite →</a>');p.write_text(h)
